#!/usr/bin/env bash\n\n# Test suite for nightly-ssh-key-rotator\n\nset -euo pipefail\n\n# Create a temporary directory for mock binaries\nMOCK_BIN_DIR=$(mktemp -d)\n\n# Mock ssh that records its invocations\nMOCK_LOG=$(mktemp)\ncat > "$MOCK_BIN_DIR/ssh" <<'EOF'\n#!/usr/bin/env bash\n# Record all arguments to a log file\nprintf "%s\n" "$@" >> "${MOCK_LOG}"\n# Simulate successful execution\nexit 0\nEOF\nchmod +x "$MOCK_BIN_DIR/ssh"\n\n# Prepend mock directory to PATH so our script picks it up\nexport PATH="$MOCK_BIN_DIR:$PATH"\n\n# Prepare a hosts file with two entries\nHOSTS_FILE=$(mktemp)\necho "host1.example.com" > "$HOSTS_FILE"\necho "host2.example.com" >> "$HOSTS_FILE"\n\n# Locate the utility script\nSCRIPT_DIR=$(cd "$(dirname "${BASH_SOURCE[0]}")/../src" && pwd)\n\n# Run the rotator (no old fingerprint supplied)\n# Capture the private key output but discard it\n"$SCRIPT_DIR/rotate_ssh_keys.sh" -u testuser -f "$HOSTS_FILE" > /dev/null\n\n# Verify that ssh was invoked exactly once per host (2 total calls)\nCALL_COUNT=$(grep -c "testuser@" "$MOCK_LOG")\nif [[ "$CALL_COUNT" -ne 2 ]]; then\n  echo "Expected 2 ssh calls, got $CALL_COUNT"\n  echo "Log contents:"\n  cat "$MOCK_LOG"\n  exit 1\nfi\n\n# Clean up temporary files\nrm -rf "$MOCK_BIN_DIR" "$MOCK_LOG" "$HOSTS_FILE"\n\necho "All tests passed."
